import heapq

def kthLargestNumber(nums: List[str], k: int) -> str:
    # Convert strings to integers for comparison, but keep original strings
    heap = []

    for num in nums:
        # Push negative values to simulate max heap behavior with min heap
        heapq.heappush(heap, -int(num))

    # Pop k-1 elements to get the kth largest at the top
    for _ in range(k - 1):
        heapq.heappop(heap)

    return str(-heapq.heappop(heap))

