            if students[student_idx][i] == mentors[mentor_idx][i]:
                score += 1
        return score

    memo = {}

    def backtrack(student_id: int, used_mentors: tuple) -> int:
        if student_id == m:
            return 0

        if (student_id, used_mentors) in memo:
            return memo[(student_id, used_mentors)]

