class AuthenticationManager {

    int timeToLive;
    TreeSet<Integer> treeSet;
    Map<String, Integer> map;
    public AuthenticationManager(int timeToLive) {
        this.timeToLive = timeToLive;
        treeSet = new TreeSet<>();
        map = new HashMap<>();
    }

    public void generate(String tokenId, int currentTime) {
        map.put(tokenId, currentTime + timeToLive);
        treeSet.add(currentTime + timeToLive);
    }

    public void renew(String tokenId, int currentTime) {

        Integer time = map.get(tokenId);
        if (time == null || time <= currentTime) return;


        // Update the hashmap and treeSet with the new values
        map.put(tokenId, currentTime + timeToLive);
        treeSet.remove(time);
        treeSet.add(currentTime + timeToLive);
    }

    public int countUnexpiredTokens(int currentTime) {

        // Remove all expired tokens from both data structures
        while (!treeSet.isEmpty() && treeSet.first() <= currentTime) {
            int earliestExpiry = treeSet.pollFirst();
            Iterator<Map.Entry<String, Integer>> iterator = map.entrySet().iterator();
            while (iterator.hasNext()) {
                Map.Entry<String, Integer> entry = iterator.next();
                if (entry.getValue() == earliestExpiry) {
                    iterator.remove();
                    break;
                }
            }
        }

        return map.size();
    }
}
