def strange_printer(s: str) -> int:
    if not s:
        return 0

    n = len(s)
    # dp[i][j] represents the minimum number of turns needed to print s[i:j+1]
    dp = [[0] * n for _ in range(n)]

    # Fill the DP table from right to left
    for i in range(n - 1, -1, -1):
        # Base case: a single character needs one turn
        dp[i][i] = 1

        # For each position j after i
        for j in range(i + 1, n):
            if s[i] == s[j]:
                # If the first and last characters are same,
                # we can print them together in one turn
                dp[i][j] = dp[i][j - 1]
            else:
                # Otherwise, try all possible partitions
                # and take the minimum
                dp[i][j] = float('inf')
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    return dp[0][n - 1]

