def longestDecomposition(text: str) -> int:
    n = len(text)
    if n == 0:
        return 0
    if n == 1:
        return 1

    # Try all possible prefix/suffix pairs starting from the smallest length
    for i in range(1, (n // 2) + 1):
        if text[:i] == text[n-i:n]:
            return 2 + longestDecomposition(text[i:n-i])

    # If no palindromic decomposition found, we have to take the whole string as one piece
    return 1

